    per_group = max(1, (n_periods + 3) // 4)
    idx = 0
    for start in range(0, n_periods, per_group):
        end = min(n_periods, start + per_group)
        group_vars = [f"y_{i}_{t}" for t in range(start, end) for i in range(n_items)]
        groups[f"periods_{idx}"] = group_vars
        idx += 1

    # Ensure at least 4 groups by splitting if needed.
    if len(groups) < 4 and n_periods > 0:
        all_groups = list(groups.items())
        groups = {}
        flat = [v for _, vs in all_groups for v in vs]
        chunk = max(1, len(flat) // 4)
        for k, start in enumerate(range(0, len(flat), chunk)):
            groups[f"chunk_{k}"] = flat[start : start + chunk]

    return groups

